// @ts-ignore: generated by opennextjs-cloudflare build
import nextWorker from "../.open-next/worker.js";
import { dispatchBillingRenewals, type BillingEnv } from "./workflows/billingRenew";

// Workflow 클래스는 워커 메인 모듈에서 export돼야 wrangler.toml의 [[workflows]] 바인딩이 찾을 수 있다
export { BillingRenewWorkflow } from "./workflows/billingRenew";

interface Env extends BillingEnv {
  NEXT_PUBLIC_SUPABASE_URL: string;
  NEXT_PUBLIC_SUPABASE_ANON_KEY: string;
  INTERNAL_API_SECRET: string;
}

interface ScheduledEvent {
  cron: string;
}

export default {
  ...nextWorker,
  async scheduled(event: ScheduledEvent, env: Env, _ctx: unknown) {
    // Supabase 슬립 방지용 keep-alive
    await fetch(
      `${env.NEXT_PUBLIC_SUPABASE_URL}/rest/v1/companies?select=id&limit=1`,
      {
        headers: {
          apikey: env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
          Authorization: `Bearer ${env.NEXT_PUBLIC_SUPABASE_ANON_KEY}`,
        },
      }
    );

    // 매일 18:00 UTC(KST 03:00) — 체험 종료·구독 만료된 매장마다 정기결제 Workflow를 하나씩 시작
    // (결제/재시도/강등은 src/workflows/billingRenew.ts에서 구독별로 따로, 단계별 결과를 기억하며 처리)
    if (event.cron === "0 18 * * *") {
      try {
        await dispatchBillingRenewals(env);
      } catch (err) {
        console.error("[scheduled] billing-renew dispatch 실패:", err);
      }
    }

    // 매일 16:00 UTC(KST 01:00) — 예약일이 지났는데 미확정 상태인 예약 자동 완료 처리
    if (event.cron === "0 16 * * *") {
      try {
        await fetch("https://www.flo-aide.com/api/cron/auto-complete-reservations", {
          method: "POST",
          headers: { "x-internal-secret": env.INTERNAL_API_SECRET },
        });
      } catch (err) {
        console.error("[scheduled] auto-complete-reservations 호출 실패:", err);
      }
    }
  },
};
